<script setup>import{Head,Link,router}from'@inertiajs/vue3';import AppLayout from'../../Layouts/AppLayout.vue';const p=defineProps({submissions:Object,statuses:Array,filters:Object});const go=()=>router.get(location.pathname,p.filters,{preserveState:true});</script><template><AppLayout><Head title="تکالیف"/><section class="rounded-2xl border bg-white p-5"><h1 class="text-xl font-bold">ارسال‌های تکالیف</h1><div class="my-4 flex gap-3"><select v-model="filters.status" @change="go"><option value="">همه وضعیت‌ها</option><option v-for="s in statuses" :value="s.value">{{s.label}}</option></select><select v-model="filters.late" @change="go"><option value="">همه</option><option value="1">با تأخیر</option><option value="0">به‌موقع</option></select></div><Link v-for="s in submissions.data" :href="`/submissions/${s.id}`" class="mb-3 block rounded-xl border p-4"><div class="flex justify-between"><strong>{{s.assignment.title}}</strong><span>{{s.status}}</span></div><p>{{s.student.first_name}} {{s.student.last_name}} — {{s.assignment.lesson.course.title}} / {{s.assignment.lesson.title}}</p><p class="text-sm">تلاش {{s.attempt_number}} <span v-if="s.is_late" class="text-red-700">— با تأخیر</span></p></Link><div class="flex gap-2"><Link v-for="l in submissions.links" :href="l.url||'#'" v-html="l.label" class="rounded border px-3 py-1"/></div></section></AppLayout></template>
